ALTER TABLE public.chronicles_dsl_branches DROP CONSTRAINT chronicles_dsl_branches_data_check, ADD CONSTRAINT chronicles_dsl_branches_data_check CHECK ((data ?& ARRAY['schema','events','links','objects','summary']) AND jsonb_typeof(data)='object' AND jsonb_typeof(data->'events')='array' AND jsonb_typeof(data->'links')='array' AND jsonb_typeof(data->'objects')='array' AND data->>'schema'='1' AND octet_length(data::text)<=10000000), DROP CONSTRAINT chronicles_dsl_branches_base_snapshot_check, ADD CONSTRAINT chronicles_dsl_branches_base_snapshot_check CHECK (base_snapshot IS NULL OR octet_length(base_snapshot::text)<=10000000);
